17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Objects;
24	import java.util.function.Function;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
44	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
45	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    private final TelephoneNormalizer telephoneNormalizer;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper,
77	                                 TelephoneNormalizer telephoneNormalizer) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	        this.telephoneNormalizer = telephoneNormalizer;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        rejectBlankOwnerFields(ownerFieldsDto);
114	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
115	        rejectDuplicateTelephone(normalizedTelephone);
116	        ownerFieldsDto.setTelephone(normalizedTelephone);
117	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        if (owner.getRegistrationDate() == null) {
121	            owner.setRegistrationDate(LocalDate.now());
122	        }
123	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
124	        this.clinicService.saveOwner(owner);
125	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
126	        headers.setLocation(UriComponentsBuilder.newInstance()
127	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
128	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
134	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
135	        if (currentOwner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        currentOwner.setAddress(ownerFieldsDto.getAddress());
139	        currentOwner.setCity(ownerFieldsDto.getCity());
140	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
141	        currentOwner.setLastName(ownerFieldsDto.getLastName());
142	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
143	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
144	        this.clinicService.saveOwner(currentOwner);
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Transactional
150	    @Override
151	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
152	        Owner owner = this.clinicService.findOwnerById(ownerId);
153	        if (owner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        this.clinicService.deleteOwner(owner);
157	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
163	        Owner owner = this.clinicService.findOwnerById(ownerId);
164	        if (owner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        HttpHeaders headers = new HttpHeaders();
168	        Pet pet = petMapper.toPet(petFieldsDto);
169	        owner.setId(ownerId);
170	        pet.setOwner(owner);
171	        pet.getType().setName(null);
172	        this.clinicService.savePet(pet);
173	        PetDto petDto = petMapper.toPetDto(pet);
174	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
175	            .buildAndExpand(pet.getId()).toUri());
176	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
182	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
183	        if (currentOwner != null) {
184	            Pet currentPet = this.clinicService.findPetById(petId);
185	            if (currentPet != null) {
186	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
187	                currentPet.setName(petFieldsDto.getName());
188	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
189	                this.clinicService.savePet(currentPet);
190	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
191	            }
192	        }
193	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
199	        HttpHeaders headers = new HttpHeaders();
200	        Visit visit = visitMapper.toVisit(visitFieldsDto);
201	        Pet pet = new Pet();
202	        pet.setId(petId);
203	        visit.setPet(pet);
204	        this.clinicService.saveVisit(visit);
205	        VisitDto visitDto = visitMapper.toVisitDto(visit);
206	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
207	            .buildAndExpand(visit.getId()).toUri());
208	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
209	    }
210	
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner != null) {
217	            Pet pet = owner.getPet(petId);
218	            if (pet != null) {
219	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
220	            }
221	        }
222	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	    }
224	
225	    /**
226	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
227	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
228	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
229	     * blank (e.g. {@code "   "}). The offending field names are reported through an
230	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
231	     * as a 400 response carrying an {@code errors} array of field names.
232	     *
233	     * @param ownerFieldsDto the submitted owner fields
234	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
235	     */
236	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
237	        List<String> blankFields = new ArrayList<>();
238	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
239	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
240	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
241	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
242	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
243	        if (!blankFields.isEmpty()) {
244	            throw new InvalidOwnerFieldsException(blankFields);
245	        }
246	    }
247	
248	    private void addIfBlank(List<String> blankFields, String field, String value) {
249	        if (value != null && value.isBlank()) {
250	            blankFields.add(field);
251	        }
252	    }
253	
254	    /**
255	     * Normalizes an owner's optional email address. When present it is stored and returned
256	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
257	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
258	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
259	     * method runs.
260	     *
261	     * @param email the raw email value from the request, or {@code null} when omitted
262	     * @return the lower-cased email, or {@code null} when none was supplied
263	     */
264	    private String normalizeEmail(String email) {
265	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
266	    }
267	
268	    /**
269	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
270	     * {@code '<LAST3>-<NNNN>'}: {@code LAST3} is the upper-cased first three letters of the
271	     * owner's {@code lastName}, and {@code NNNN} is a global 4-digit zero-padded sequence equal
272	     * to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
273	     *
274	     * @param lastName the last name of the owner being created
275	     * @return the formatted customer code
276	     */
277	    private String nextCustomerCode(String lastName) {
278	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
279	        long sequence = this.clinicService.findAllOwners().size() + 1L;
280	        return String.format("%s-%04d", last3, sequence);
281	    }
282	
283	    /**
284	     * Rejects a create request whose normalized telephone is already used by any existing owner.
285	     * Existing owners' telephones are reduced to the same canonical form (via
286	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
287	     * only in formatting still collide. A collision is reported through a
288	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
289	     * as a 409 Conflict response.
290	     *
291	     * @param normalizedTelephone the canonical telephone of the owner being created
292	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
293	     */
294	    private void rejectDuplicateTelephone(String normalizedTelephone) {
295	        boolean duplicate = existingOwnerMatches(
296	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
297	            normalizedTelephone);
298	        if (duplicate) {
299	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
300	        }
301	    }
302	
303	    /**
304	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
305	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
306	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
307	     * and the owner being created to the same canonical key and reject a match.
308	     *
309	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
310	     * @param key the canonical key of the owner being created
311	     * @return {@code true} if some existing owner shares the key
312	     */
313	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
314	        return this.clinicService.findAllOwners().stream()
315	            .map(keyExtractor)
316	            .filter(Objects::nonNull)
317	            .anyMatch(key::equals);
318	    }
319	}
